Method.Implementation:
    Set pStatus=""
    Set count=0

    New $NAMESPACE
    Try {
        Set $NAMESPACE=pNamespace
    } Catch ex {
        Set pStatus="CANNOT ENTER NAMESPACE"
        Goto Done
    }

    If '$Data(^Ens.MessageHeaderI("TimeCreated")) {
        If $Data(^Ens.MessageHeaderD) {
            Set pStatus="HAS MessageHeaderD, NO TimeCreated INDEX"
        } Else {
            Set pStatus="NO MessageHeaderD / MessageHeaderI"
        }
        Goto Done
    }

    Set minTS=$Order(^Ens.MessageHeaderI("TimeCreated",""))
    Set maxTS=$Order(^Ens.MessageHeaderI("TimeCreated",""),-1)

    If minTS="" {
        Set pStatus="TimeCreated INDEX EMPTY"
        Goto Done
    }

    ; Use ]] for string-collation comparisons on timestamps
    If (minTS ]] pEndTS) || (pStartTS ]] maxTS) {
        Set pStatus="OUTSIDE RANGE min="_minTS_" max="_maxTS
        Set count=0
        Goto Done
    }

    Set count=..CountUsingTimeCreatedIndex(pStartTS,pEndTS)
    Set pStatus="OK min="_minTS_" max="_maxTS

Done
    Quit count

Method.Description:
One-call JSON summary with per-namespace breakdowns (ALL are "to date").
Returns:
{
  "as_of":"YYYY-MM-DD HH:MM:SS",
  "day_to_date":{"total":N,"by_namespace":{...},"excluded":{...}},
  "week_to_date":{"total":N,"by_namespace":{...},"excluded":{...}},
  "month_to_date":{"total":N,"by_namespace":{...},"excluded":{...}}
}
